    size_t off = 0;
    if (off + 4 > buf.size()) return 3;
    if (std::memcmp(buf.data(), "PAK1", 4) != 0) return 3;
    off = 4;
    if (off + 4 > buf.size()) return 3;
    uint32_t entry_count = 0;
    std::memcpy(&entry_count, buf.data() + off, 4);
    off += 4;

    for (uint32_t i = 0; i < entry_count; ++i) {
        if (off + 2 > buf.size()) return 3;
        uint16_t name_len = 0;
        std::memcpy(&name_len, buf.data() + off, 2);
        off += 2;
        if (off + name_len > buf.size()) return 3;
        std::string name(reinterpret_cast<const char*>(buf.data() + off), name_len);
        off += name_len;
        if (!safe_name(name)) return 2;

        if (off + 10 > buf.size()) return 3;
        uint8_t method = buf[off];
        uint32_t stored_size = 0, original_size = 0;
        std::memcpy(&stored_size, buf.data() + off + 1, 4);
        std::memcpy(&original_size, buf.data() + off + 5, 4);
        off += 10;

        if (off + stored_size > buf.size()) return 3;
        const uint8_t* data = buf.data() + off;

        if (method == 0) { // stored
            if (static_cast<size_t>(stored_size) != original_size) return 3;
            Entry e;
            e.name = name;
            e.data.insert(e.data.end(), data, data + stored_size);
            out.push_back(e);
        } else if (method == 1) { // RLE
            Entry e;
            e.name = name;
            if (original_size == 0 || stored_size == 0 || original_size > (1u << 30)) return 3;
            std::vector<uint8_t> decoded;
            decoded.reserve(original_size);
            size_t pos = 0;
            for (uint32_t j = 0; j < stored_size; ++j) {
                uint8_t c = data[j];
                if (c == 0) return 3; // invalid RLE count 0
                if (pos >= original_size) return 3;
                if (pos + static_cast<size_t>(c) > original_size) return 3; // overflow
                ++j;
                if (j + 1 >= stored_size) return 3; // need a following byte
                uint8_t byte = data[j];
                pos += c;
                for (size_t k = 0; k < static_cast<size_t>(c); ++k) decoded.push_back(byte);
            }
            if (pos != static_cast<size_t>(original_size)) return 3; // decoded length mismatch
            e.data.swap(decoded);
            out.push_back(e);
        } else {
            return 3; // unknown method
        }
    }
    if (off != buf.size()) return 3; // trailing bytes
    return 0;
}

} // namespace

int main(int argc, char** argv) {
    if (argc != 3) {
        std::cerr << "usage: unpack <archive> <outdir>\n";
        return 1;
    }
    const std::string archive = argv[1];
    const std::string outdir = argv[2];

    std::error_code ec;
    auto path = std::filesystem::path(archive);

    // Read entire archive.
    std::vector<uint8_t> buf;
    {
        std::ifstream in(path, std::ios::binary);
        if (!in) {
            std::cerr << "error: cannot open archive " << path << "\n";
            return 3;
        }
        buf.resize(std::filesystem::file_size(path));
        if (!buf.empty() && !in.read(reinterpret_cast<char*>(buf.data()), static_cast<std::streamsize>(buf.size()))) {
            std::cerr << "error: truncated archive " << path << "\n";
            return 3;
        }
    }

    std::vector<Entry> entries;
    int rc = validate_archive(buf, entries);
    if (rc == 3) {
        std::cerr << "error: corrupt archive " << path << "\n";
        return 3;
    }
    if (rc == 2) {
        std::cerr << "error: unsafe entry name in " << path << "\n";
        return 2;
    }

    // Nothing written yet: safe to create outdir.
    std::filesystem::create_directories(outdir, ec);
    if (ec) {
        std::cerr << "error: cannot create output directory " << outdir << "\n";
        return 1;
    }

    for (const Entry& e : entries) {
        std::string target = outdir + '/' + e.name;
        size_t slash = 0;
        while (true) {
            slash = e.name.find('/', slash);
            if (slash == std::string::npos) break;
            std::string parent = outdir + '/' + e.name.substr(0, slash);
            std::error_code pec;
            if (!std::filesystem::exists(parent, pec)) {
                std::filesystem::create_directories(parent, pec);
            }
            if (pec) {
                std::cerr << "error: cannot create directory " << parent << "\n";
                return 1;
            }
            slash++;
        }
        std::ofstream out(target, std::ios::binary | std::ios::trunc);
        if (!out) {
            std::cerr << "error: cannot write file " << target << "\n";
            return 1;
        }
        out.write(reinterpret_cast<const char*>(e.data.data()), static_cast<std::streamsize>(e.data.size()));
        out.close();
        if (!out) {
            std::cerr << "error: write failed for " << target << "\n";
            return 1;
        }
    }
    return 0;
}
